import json, math

def by_variant(samples):
    d={}
    for s in samples: d.setdefault(s['variant'],[]).append(s)
    return d

def best_of_m_per_variant_majority(samples, m):
    d = by_variant(samples)
    picks = []
    for v, lst in d.items():
        sub = lst[:m]
        if not sub: continue
        best = max(sub, key=lambda s: s['score'])
        picks.append(best['answer'])
    counts={}
    for a in picks: counts[a]=counts.get(a,0)+1
    return max(counts.items(), key=lambda x:x[1])[0]

for f in ['alg_deep.json','geo_deep.json','comb_deep.json','nt_deep.json']:
    qs = json.load(open(f))['questions']
    n=len(qs)
    print('===',f)
    for m in [1,2,3,4,6]:
        acc=0
        for q in qs:
            if best_of_m_per_variant_majority(q['samples'], m)==q['correct_answer']: acc+=1
        print(f'  m={m} (total~{5*m} samples) acc={acc/n:.3f}')
